import { ChevronRight, Copy, Search, ShieldAlert, X } from "lucide-react";
import { useMemo, useState } from "react";

import { Page, useCrumbs } from "@/components/page";
import catalog from "@/generated/cli.json";
import { useCli, useStatus } from "@/hooks/use-daemon";
import { subById, viewById } from "@/lib/nav";
import { copyText } from "@/lib/system";
import { cn } from "@/lib/utils";
import { t } from "@/lib/i18n";
import { tx } from "@/lib/i18n-jsx";

/** Generated by `make cli-catalog` from the CLI's own definitions. */
interface Entry {
  usage: string;
  name: string;
  about: string;
  details: string | null;
  aliases: string[];
  args: {
    name: string;
    positional: boolean;
    required: boolean;
    takes_value: boolean;
    help: string;
    default: string | null;
  }[];
  since: string;
  privileged: boolean;
  examples: string[];
  notes: string[];
}

const CATEGORIES = catalog.categories as { id: string; label: string; commands: Entry[] }[];

function matches(entry: Entry, needle: string) {
  if (!needle) return true;
  return [
    entry.usage,
    entry.about,
    entry.details ?? "",
    ...entry.aliases,
    ...entry.examples,
    ...entry.args.map((a) => `${a.name} ${a.help}`),
  ]
    .join(" ")
    .toLowerCase()
    .includes(needle);
}

export function CliView() {
  const view = viewById("tools");
  const sub = subById(view, "cli")!;
  const crumbs = useCrumbs(view, sub);
  // The catalog is built from the CLI the app bundles, so its version is that
  // CLI's (the daemon's when the bundled one isn't found).
  const cli = useCli().query.data;
  const status = useStatus().data;
  const version = cli?.version ?? status?.version ?? "—";
  const [query, setQuery] = useState("");
  const needle = query.trim().toLowerCase();

  const shown = useMemo(
    () =>
      CATEGORIES.map((c) => ({ ...c, commands: c.commands.filter((e) => matches(e, needle)) })).filter(
        (c) => c.commands.length,
      ),
    [needle],
  );
  const total = CATEGORIES.reduce((n, c) => n + c.commands.length, 0);

  return (
    <Page
      view={view}
      title={sub.label}
      description={
        <>
          Everything here also works from a terminal with{" "}
          <span className="font-mono text-foreground">{t("locdev")}</span>, which talks to the same daemon. Add{" "}
          <span className="font-mono text-foreground">{t("--json")}</span> to any command for machine-readable output.
        </>
      }
      crumbs={crumbs}
      wide
    >
      <label className="flex h-9 items-center gap-2 rounded-md border bg-background/60 px-3 text-sm focus-within:border-ember/50">
        <Search className="size-4 text-muted-foreground" />
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={(e) => e.key === "Escape" && setQuery("")}
          placeholder={t("Search {total} commands, flags and examples", { total })}
          aria-label={t("Search commands")}
          className="min-w-0 flex-1 bg-transparent outline-none placeholder:text-muted-foreground"
        />
        {query && (
          <button type="button" aria-label={t("Clear search")} onClick={() => setQuery("")}>
            <X className="size-3.5 text-muted-foreground" />
          </button>
        )}
      </label>

      {!shown.length && (
        <p className="text-sm text-muted-foreground">{t("No command matches “{query}”.", { query })}</p>
      )}

      {shown.map((category) => (
        <section key={category.id} className="flex flex-col">
          <h2 className="mb-1 border-b pb-2 font-mono text-[11px] tracking-[0.08em] text-muted-foreground uppercase">
            {category.label}
          </h2>
          <ul>
            {category.commands.map((entry) => (
              <CommandRow key={entry.name} entry={entry} open={!!needle} />
            ))}
          </ul>
        </section>
      ))}

      <p className="font-mono text-[11px] text-muted-foreground">
        {tx(
          "Catalog of locdev {version}. Commands marked {admin} show the exact change and ask before using administrator rights.",
          { version, admin: <span className="text-amber">{t("admin")}</span> },
        )}
      </p>
    </Page>
  );
}

function CommandRow({ entry, open: forced }: { entry: Entry; open: boolean }) {
  const [open, setOpen] = useState(false);
  const expanded = open || forced;
  const hasMore = entry.args.length > 0 || entry.examples.length > 0 || entry.notes.length > 0 || !!entry.details;

  return (
    <li className="border-b border-dashed last:border-b-0">
      <div className="flex items-center gap-3 py-2">
        <button
          type="button"
          onClick={() => setOpen(!open)}
          disabled={!hasMore}
          aria-expanded={expanded}
          className="flex min-w-0 flex-1 items-center gap-2 text-left"
        >
          <ChevronRight
            className={cn(
              "size-3.5 shrink-0 text-muted-foreground transition-transform",
              expanded && "rotate-90",
              !hasMore && "invisible",
            )}
          />
          <span className="shrink-0 font-mono text-[13px]">{entry.usage}</span>
          <span className="min-w-0 truncate text-[13px] text-muted-foreground">{entry.about}</span>
        </button>
        <span className="flex shrink-0 items-center gap-1.5 font-mono text-[10.5px]">
          {entry.aliases.map((alias) => (
            <span key={alias} className="rounded border px-1 text-muted-foreground" title={t("alias")}>
              {alias}
            </span>
          ))}
          {entry.privileged && (
            <span
              className="flex items-center gap-1 rounded border border-amber/40 px-1 text-amber"
              title={t("Asks for administrator rights")}
            >
              <ShieldAlert className="size-3" /> {t("admin")}
            </span>
          )}
          <span className="text-muted-foreground/70" title={t("Available since")}>
            v{entry.since}
          </span>
          <button
            type="button"
            aria-label={t("Copy {usage}", { usage: entry.usage })}
            onClick={() => copyText(entry.usage)}
            className="rounded p-1 text-muted-foreground hover:bg-foreground/6 hover:text-foreground"
          >
            <Copy className="size-3.5" />
          </button>
        </span>
      </div>

      {expanded && hasMore && (
        <div className="mb-3 ml-6 flex flex-col gap-3 text-[13px]">
          {entry.details && entry.details !== entry.about && (
            <p className="whitespace-pre-line text-muted-foreground">{entry.details}</p>
          )}
          {entry.args.length > 0 && (
            <dl className="grid grid-cols-[minmax(9rem,auto)_1fr] gap-x-4 gap-y-1 font-mono text-[12px]">
              {entry.args.map((arg) => (
                <div key={arg.name} className="contents">
                  <dt className={cn(arg.positional ? "text-foreground" : "text-ember")}>
                    {arg.name}
                    {arg.takes_value && !arg.positional && (
                      <span className="text-muted-foreground"> {t("<value>")}</span>
                    )}
                    {!arg.required && arg.positional && <span className="text-muted-foreground">?</span>}
                  </dt>
                  <dd className="font-sans text-[13px] text-muted-foreground">
                    {arg.help || "—"}
                    {arg.default && (
                      <span className="font-mono text-[11.5px]">
                        {" "}
                        {t("(default {default})", { default: arg.default })}
                      </span>
                    )}
                  </dd>
                </div>
              ))}
            </dl>
          )}
          {entry.examples.length > 0 && (
            <div className="overflow-hidden rounded-lg border bg-well">
              {entry.examples.map((example) => (
                <button
                  type="button"
                  key={example}
                  onClick={() => copyText(example)}
                  className="flex w-full items-center justify-between border-b px-3 py-1.5 text-left font-mono text-xs transition-colors last:border-b-0 hover:bg-foreground/3"
                >
                  <span>
                    <span className="text-ember">$</span> {example}
                  </span>
                  <span className="text-[10.5px] text-muted-foreground">{t("copy")}</span>
                </button>
              ))}
            </div>
          )}
          {entry.notes.map((note) => (
            <p key={note} className="text-[12.5px] text-muted-foreground">
              {note}
            </p>
          ))}
        </div>
      )}
    </li>
  );
}
